mapper.update:
UPDATE scx_ocpx_monitor_task SET rta_enabled=#{enabled},
update_time=NOW(3)
WHERE id=#{task}

choose.when:
SELECT t.id AS monitor_task_id, r.strategy_id, r.oppo_pkg, ma.protocol AS media_protocol, ma.credential_ref AS media_access_code, t.monitor_name AS task_name, t.media_id, t.advertiser_id, m.media_name AS media_name, a.advertiser_name AS advertiser_name, r.upstream_id, r.product_id, r.external_task_id, u.protocol, COALESCE(r.version, 0) AS version, COALESCE(r.enabled, 0) AS enabled FROM scx_ocpx_monitor_task t LEFT JOIN scx_ocpx_rta_binding r ON r.monitor_task_id=t.id LEFT JOIN scx_ocpx_rta_upstream u ON u.id=r.upstream_id LEFT JOIN scx_ocpx_rta_media_access ma ON ma.media_id=t.media_id JOIN scx_ocpx_media m ON m.id=t.media_id JOIN scx_ocpx_advertiser a ON a.id=t.advertiser_id WHERE 1=1 AND t.is_delete=0
AND t.advertiser_id=#{q.advertiserId}
AND t.media_id=#{q.filters.mediaId}
AND t.id=#{q.filters.monitorTaskId}
AND COALESCE(r.enabled, 0)=
1
0
AND t.monitor_name LIKE CONCAT('%', #{q.filters.keyword}, '%')

SELECT r.*,
m.media_name,
t.monitor_name AS task_name
FROM scx_ocpx_rta_log r
LEFT
JOIN scx_ocpx_media m ON m.id=r.media_id
LEFT
JOIN scx_ocpx_monitor_task t ON t.id=r.task_id
WHERE 1=1

    AND r.advertiser_id=#{q.advertiserId}


    AND r.media_id=#{q.filters.mediaId}


    AND r.task_id=#{q.filters.monitorTaskId}


    AND r.upstream_id=#{q.filters.upstreamId}

AND r.event_time BETWEEN #{q.start} AND #{q.end} AND r.event_time>=#{q.retentionStart}

    AND r.request_id=#{q.filters.requestId}


    AND r.relay_request_id=#{q.filters.relayRequestId}


    AND r.stage=#{q.filters.stage}


    AND r.status=#{q.filters.status}

SELECT r.*,
m.media_name,
t.monitor_name AS task_name
FROM scx_ocpx_rta_hour_stat r
LEFT
JOIN scx_ocpx_media m ON m.id=r.media_id
LEFT
JOIN scx_ocpx_monitor_task t ON t.id=r.task_id
WHERE 1=1

    AND r.advertiser_id=#{q.advertiserId}


    AND r.media_id=#{q.filters.mediaId}


    AND r.task_id=#{q.filters.monitorTaskId}


    AND r.upstream_id=#{q.filters.upstreamId}

AND r.time_hour BETWEEN #{q.start} AND #{q.end}

