choose.when:
SELECT r.id, r.monitor_name AS name FROM scx_ocpx_monitor_task r WHERE 1=1 AND r.is_delete=0
AND r.media_id=#{q.filters.mediaId}
AND r.advertiser_id=#{q.advertiserId}
AND (r.monitor_name LIKE CONCAT('%', #{q.filters.keyword}, '%') OR r.id=#{q.filters.keyword})
ORDER BY r.monitor_name, r.id LIMIT 100

mapper.select:
SELECT COUNT(*)
FROM scx_ocpx_rta_upstream u
JOIN scx_ocpx_rta_media_access m ON m.media_id=#{mediaId}
WHERE u.id=#{upstreamId} AND u.advertiser_id=#{advertiserId}

    AND u.enabled=1 AND m.enabled=1

SELECT COUNT(*)
FROM scx_ocpx_advertiser
WHERE id=#{id}

SELECT COUNT(*)
FROM scx_ocpx_media
WHERE id=#{id}
